def unpack(code):
    return json.loads(zlib.decompress(base64.b85decode(code)).decode('utf8'))

def main():
    here=Path(__file__).resolve().parent
    paths=[Path(sys.argv[1]).expanduser().resolve()] if len(sys.argv)>1 else [here,here/'web',Path.cwd(),Path.cwd()/'web']
    base=next((x for x in paths if (x/'src/game/fighter.ts').is_file()),None)
    if base is None:
        print('ERROR: Put this installer in your Fight Royale web folder, or pass the full web path.')
        return 1
    fighter=base/'src/game/fighter.ts'
    ai=base/'src/game/ai.ts'
    game=base/'src/game/game.ts'
    if not (ai.is_file() and game.is_file()):
        print('ERROR: The game AI or game.ts is missing. Nothing changed.');return 2
    ai_source=ai.read_text(encoding='utf8')
    fighter_source=fighter.read_text(encoding='utf8')
    game_source=game.read_text(encoding='utf8')
    if 'ZENITH_BLEED_DANCE_AI_V11_20261108' in ai_source:
        if 'ZENITH_HIT_TEMPO_V1' in fighter_source and 'ZENITH_BLEED_TEMPO_V1' in game_source:
            print('Everything is already installed.');return 0
        print('ERROR: The Zenith AI was applied but the combat patch is missing. Nothing changed.');return 3
    # If previous full combat patch was already installed, upgrade ONLY AI.
    prior = 'ZENITH_HIT_TEMPO_V1' in fighter_source and 'ZENITH_BLEED_TEMPO_V1' in game_source
    if prior and 'ANTI_ZENITH_CPU_V1' not in ai_source:
        print('ERROR: Partial/unsupported earlier patch. Nothing changed.');return 3
    if not prior and ('ZENITH_HIT_TEMPO_V1' in fighter_source or 'ZENITH_BLEED_TEMPO_V1' in game_source):
        print('ERROR: Partial combat patch. Nothing changed.');return 3
    edits=unpack(ZENITH_AI_DATA if prior else DATA)
    changed={}
    for rel,steps in edits.items():
        path=base/rel
        if not path.is_file():
            print('ERROR: Missing '+str(path)+'. Nothing changed.');return 4
        before=path.read_text(encoding='utf8');after=before
        for idx,e in enumerate(steps,1):
            old,new=e['old'],e['new']
            if old in after:
                if after.count(old)!=1:
                    print(f'ERROR: Duplicate anchor {rel}, change {idx}. Nothing changed.');return 5
                after=after.replace(old,new,1)
            elif new in after:
                pass
            else:
                print(f'ERROR: Incompatible {rel}, change {idx}. Nothing changed.')
                print('Your files differ from the Nov 8 source; update the installer using your current src ZIP.')
                return 6
        if after!=before:changed[path]=(before,after)
    if not changed:
        print('No changes necessary.');return 0
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backups=[];temps=[]
    try:
        for p in changed:
            bak=p.with_name(p.name+f'.before_{PATCH_TAG}_{stamp}.bak')
            shutil.copy2(p,bak);backups.append((p,bak))
        for p,(_,updated) in changed.items():
            tmp=p.with_name(p.name+f'.tmp_{PATCH_TAG}')
            tmp.write_text(updated,encoding='utf8');temps.append(tmp)
            tmp.replace(p)
            print('UPDATED',p.relative_to(base))
    except Exception as err:
        for p,bak in backups:shutil.copy2(bak,p)
        print('ERROR, restored original files:',err);return 7
    finally:
        for tmp in temps:
            if tmp.exists():tmp.unlink()
    print('Installed Nythera 25-second Orbit HUD and clashable combos, anti-Zenith AI,')
    print('Zenith Spearstep dash, +0.1x speed/hit (15s reset, 2.4x/3.4x caps),')
    print('5x Bleed and 5% lower basic damage, plus Zenith Bleed-Dance CPU tactics.')
    print('Run npx tsc --noEmit -p . && npm run dev')
    return 0
if __name__=='__main__':sys.exit(main())
